(()=>{'use strict';const theme=document.getElementById('theme');const updateTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';theme.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);theme.textContent=dark?'☀':'◐'};updateTheme();theme.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('buddy-theme',next)}catch{}updateTheme()});const menu=document.getElementById('menu'),nav=document.getElementById('navigation');const closeMenu=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')};menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});const dialog=document.getElementById('contact-dialog');let trigger=null;document.querySelectorAll('[data-quote]').forEach(button=>button.addEventListener('click',()=>{trigger=button;const topic=button.dataset.quote;const message=encodeURIComponent(`Hi, I would like to enquire about ${topic} at Buddy Computers. My requirement is: `);document.getElementById('wa-navin').href=`https://wa.me/917096310195?text=${message}`;document.getElementById('wa-shubham').href=`https://wa.me/917426933642?text=${message}`;dialog.showModal()}));document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>trigger?.focus());})();
